node <<'EOF'
const fs = require('fs');
const tabs = JSON.parse(fs.readFileSync('/tmp/redhood-tabs.json','utf8'));
const page = tabs.find(t => t.url && t.url.includes('little-red-riding-hood'));
if (!page) { console.error('no page'); process.exit(1); }
const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
function send(method, params) {
  const i = ++id;
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error('timeout '+method)), 30000);
    pending.set(i, {resolve, reject, t});
    ws.send(JSON.stringify({id:i, method, params}));
  });
}
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const p = pending.get(msg.id);
    clearTimeout(p.t);
    pending.delete(msg.id);
    if (msg.error) p.reject(new Error(JSON.stringify(msg.error)));
    else p.resolve(msg.result);
  } else if (msg.method === 'Runtime.consoleAPICalled') {
    const a = (msg.params.args||[]).map(x => x.value ?? x.description).join(' ');
    console.log('CONSOLE', msg.params.type, a);
  } else if (msg.method === 'Runtime.exceptionThrown') {
    console.log('EXCEPTION', msg.params.exceptionDetails && msg.params.exceptionDetails.text);
  }
};
ws.onerror = (e) => { console.error('ws error', e); process.exit(1); };
(async () => {
  await new Promise(r => ws.onopen = r);
